   679→            TrieNode? child;
   680→            if (ReferenceEquals(childOrRef, _nullNode) || childOrRef is null)
   681→            {
   682→                child = null;
   683→            }
   684→            else if (childOrRef is TrieNode childNode)
   685→            {
   686→                child = childNode;
   687→            }
   688→            else if (childOrRef is Hash256 reference)
   689→            {
   690→                child = tree.FindCachedOrUnknown(childPath, reference);
   691→            }
   692→            else
   693→            {
   694→                // we expect this to happen as a Trie traversal error (please see the stack trace above)
   695→                // we need to investigate this case when it happens again
   696→                ThrowUnexpectedTypeException(childIndex, childOrRef);
   697→            }
   698→
   699→            // pruning trick so we never store long persisted paths
   700→            // Dont unresolve node of path length <= 4. there should be a relatively small number of these, enough to fit
   701→            // in RAM, but they are hit quite a lot, and don't have very good data locality.
   702→            // That said, in practice, it does nothing notable, except for significantly improving benchmark score.
   703→            if (child?.IsPersisted == true && childPath.Length > 4 && childPath.Length % 2 == 0)
   704→            {
   705→                UnresolveChild(childIndex);
   706→            }
   707→
   708→            return child;
