   760→        public long GetMemorySize(bool recursive)
   761→        {
   762→            int keccakSize = Keccak is null ? MemorySizes.RefSize : MemorySizes.RefSize + Hash256.MemorySize;
   763→            long rlpSize = _rlp.MemorySize;
   764→            long dataSize = MemorySizes.RefSize + (_nodeData?.MemorySize ?? 0);
   765→            int objectOverhead = MemorySizes.ObjectHeaderMethodTable;
   766→            int blockAndFlagsSize = sizeof(long);
   767→
   768→            if (_nodeData is BranchData data)
   769→            {
   770→                for (int i = 0; i < data.Length; i++)
   771→                {
   772→                    var child = data[i];
   773→                    dataSize += child switch
   774→                    {
   775→                        null => 0,
   776→                        Hash256 => Hash256.MemorySize,
   777→                        byte[] array => MemorySizes.ArrayOverhead + array.Length,
   778→                        CappedArray<byte> cappedArray => MemorySizes.ArrayOverhead + cappedArray.UnderlyingLength +
   779→                                                         MemorySizes.SmallObjectOverhead,
   780→                        _ => recursive && child is TrieNode node ? node.GetMemorySize(true) : 0
   781→                    };
   782→                }
   783→            }
   784→            else if (_nodeData is ExtensionData extensionData)
   785→            {
   786→                dataSize += extensionData.Value switch
   787→                {
   788→                    null => 0,
   789→                    Hash256 => Hash256.MemorySize,
   790→                    byte[] array => MemorySizes.ArrayOverhead + array.Length,
   791→                    CappedArray<byte> cappedArray => MemorySizes.ArrayOverhead + cappedArray.UnderlyingLength +
   792→                                                     MemorySizes.SmallObjectOverhead,
   793→                    _ => recursive && extensionData.Value is TrieNode node ? node.GetMemorySize(true) : 0
   794→                };
   795→            }
   796→
   797→            long unaligned = keccakSize +
   798→                             rlpSize +
   799→                             dataSize +
   800→                             blockAndFlagsSize +
   801→                             objectOverhead;
   802→
   803→            return MemorySizes.Align(unaligned);
   804→        }
