  1168→        private void SeekChildNotNull(ref ValueRlpStream rlpStream, int index)
  1169→        {
  1170→            rlpStream.Reset();
  1171→            rlpStream.SkipLength();
  1172→            if (index == 0 && IsExtension)
  1173→            {
  1174→                // Corner case, index is zero, but we are an extension
  1175→                // so we need to move to next item
  1176→                index = 1;
  1177→            }
  1178→
  1179→            for (int i = 0; i < index; i++)
  1180→            {
  1181→                rlpStream.SkipItem();
  1182→            }
  1183→        }
