  1254→        {
  1255→            int chCount = 0;
  1256→            SpanSource rlp = _rlp;
  1257→            if (rlp.IsNull)
  1258→            {
  1259→                path.AppendMut(0);
  1260→                for (int i = 0; i < 16; i++)
  1261→                {
  1262→                    path.SetLast(i);
